/**
 * SynapseEnhancedClient - Client entry point for Synapse enhanced features
 * Integrates enhanced APIs including friends management, private chat, chat room,
 * security detection, voice processing, etc.
 */
export class SynapseEnhancedClient implements ISynapseEnhancedConfig {
    public readonly baseUrl: string;
    public readonly accessToken: string;
    public readonly apiPrefix: string;
    public readonly timeout: number;

    private readonly httpClient: SynapseEnhancedHttpClient;
    private readonly _friends: FriendsApi;
    private readonly _privateChat: PrivateChatApi;
    private readonly _privateChatStatus: PrivateChatStatusApi;
    private readonly _chatroom: ChatroomApi;
    private readonly _security: SecurityApi;
    private readonly _voice: VoiceApi;
    private readonly _voiceUser: VoiceUserApi;
    private readonly _admin: AdminApi;
    private readonly _presence: PresenceApi;
    private readonly _messages: MessagesApi;
    private readonly _securityAdmin: SecurityAdminApi;
    private readonly _enhanced: EnhancedInitApi;
    private readonly _friendRequests: FriendRequestsApi;
    private readonly _friendCategories: FriendCategoriesApi;
    private readonly _blockedUsers: BlockedUsersApi;
    private readonly _privateChatAdmin: PrivateChatAdminApi;
    private readonly _audioUpload: AudioUploadApi;

    public constructor(config: ISynapseEnhancedConfig) {
        this.baseUrl = config.baseUrl.replace(/\/$/, "");
        this.accessToken = config.accessToken;
        this.apiPrefix = config.apiPrefix || "/_synapse/client";
        this.timeout = config.timeout || 30000;

        this.httpClient = new SynapseEnhancedHttpClient({
            baseUrl: this.baseUrl,
            accessToken: this.accessToken,
            apiPrefix: this.apiPrefix,
            timeout: this.timeout,
        });

        this._friends = new FriendsApi(this.httpClient);
        this._privateChat = new PrivateChatApi(this.httpClient);
        this._privateChatStatus = new PrivateChatStatusApi(this.httpClient);
        this._chatroom = new ChatroomApi(this.httpClient);
        this._security = new SecurityApi(this.httpClient);
        this._voice = new VoiceApi(this.httpClient);
        this._voiceUser = new VoiceUserApi(this.httpClient);
        this._admin = new AdminApi(this.httpClient);
        this._presence = new PresenceApi(this.httpClient);
        this._messages = new MessagesApi(this.httpClient);
        this._securityAdmin = new SecurityAdminApi(this.httpClient);
        this._enhanced = new EnhancedInitApi(this.httpClient);
        this._friendRequests = new FriendRequestsApi(this.httpClient);
        this._friendCategories = new FriendCategoriesApi(this.httpClient);
        this._blockedUsers = new BlockedUsersApi(this.httpClient);
        this._privateChatAdmin = new PrivateChatAdminApi(this.httpClient);
        this._audioUpload = new AudioUploadApi(this.httpClient);
    }

    public get friends(): IFriendsApi {
        return this._friends;
    }

    public get privateChat(): IPrivateChatApi {
        return this._privateChat;
    }

    public get privateChatStatus(): PrivateChatStatusApi {
        return this._privateChatStatus;
    }

    public get chatroom(): ChatroomApi {
        return this._chatroom;
    }

    public get security(): ISecurityApi {
        return this._security;
    }

    public get voice(): IVoiceApi {
        return this._voice;
    }

    public get admin(): IAdminApi {
        return this._admin;
    }

    public get presence(): IPresenceApi {
        return this._presence;
    }

    public get messages(): MessagesApi {
        return this._messages;
    }

    public get securityAdmin(): SecurityAdminApi {
        return this._securityAdmin;
    }

    public get enhanced(): EnhancedInitApi {
        return this._enhanced;
    }

    public get voiceUser(): VoiceUserApi {
        return this._voiceUser;
    }

    public get friendRequests(): FriendRequestsApi {
        return this._friendRequests;
    }

    public get friendCategories(): FriendCategoriesApi {
        return this._friendCategories;
    }

    public get blockedUsers(): BlockedUsersApi {
        return this._blockedUsers;
    }

    public get privateChatAdmin(): PrivateChatAdminApi {
        return this._privateChatAdmin;
    }

    public get audioUpload(): AudioUploadApi {
        return this._audioUpload;
    }

    public getHttpClient(): SynapseEnhancedHttpClient {
        return this.httpClient;
    }

    public getEnhancedClient(): {
        friends: IFriendsApi;
        privateChat: IPrivateChatApi;
        privateChatStatus: PrivateChatStatusApi;
        chatroom: ChatroomApi;
        security: ISecurityApi;
        voice: IVoiceApi;
        voiceUser: VoiceUserApi;
        admin: AdminApi;
        presence: PresenceApi;
        messages: MessagesApi;
        securityAdmin: SecurityAdminApi;
        enhanced: EnhancedInitApi;
        friendRequests: FriendRequestsApi;
        friendCategories: FriendCategoriesApi;
        blockedUsers: BlockedUsersApi;
        privateChatAdmin: PrivateChatAdminApi;
        audioUpload: AudioUploadApi;
    } {
        return {
            friends: this._friends,
            privateChat: this._privateChat,
            privateChatStatus: this._privateChatStatus,
            chatroom: this._chatroom,
            security: this._security,
            voice: this._voice,
            voiceUser: this._voiceUser,
            admin: this._admin,
            presence: this._presence,
            messages: this._messages,
            securityAdmin: this._securityAdmin,
            enhanced: this._enhanced,
            friendRequests: this._friendRequests,
            friendCategories: this._friendCategories,
            blockedUsers: this._blockedUsers,
            privateChatAdmin: this._privateChatAdmin,
            audioUpload: this._audioUpload,
        };
    }

    /**
     * Get the runtime status of Synapse enhanced features
     * @returns Status information including version, initialization state, and supported features
     */
    public async getStatus(): Promise<ISynapseStatus> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                version?: string;
                initialized: boolean;
                features: ISynapseStatus["features"];
            };
            error?: string;
        }>("/status");

        const data = handleApiResponse(response, "Failed to get status");

        return {
            version: data.version || "unknown",
            status: "healthy",
            initialized: data.initialized,
            features: data.features,
        };
    }
}

